-- IIR strict U.S.-domicile & U.S.-headquarters exchange eligibility, 2026-11-13
-- Exclusions retain all historical filings, signals, prices and score snapshots; no destructive delete.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS company_listing_verification(
 company_ticker TEXT PRIMARY KEY REFERENCES companies(ticker),
 incorporation_country TEXT NOT NULL CHECK(length(incorporation_country)=2),
 headquarters_country TEXT NOT NULL CHECK(length(headquarters_country)=2),
 primary_exchange TEXT NOT NULL CHECK(primary_exchange IN ('NYSE','NASDAQ')),
 security_type TEXT NOT NULL DEFAULT 'COMMON_STOCK' CHECK(security_type IN ('COMMON_STOCK')),
 eligibility_status TEXT NOT NULL CHECK(eligibility_status IN ('US_CONFIRMED','FOREIGN_EXCLUDED')),
 verification_source_url TEXT NOT NULL,
 verified_on TEXT NOT NULL,
 verification_note TEXT NOT NULL DEFAULT '',
 CHECK((eligibility_status='US_CONFIRMED' AND incorporation_country='US' AND headquarters_country='US') OR
       (eligibility_status='FOREIGN_EXCLUDED' AND (incorporation_country<>'US' OR headquarters_country<>'US')))
);
